return $input.all().flatMap(item => {
  // Skip items that have no data field (e.g. error responses)
  if (!item.json.data) return [];

  let raw;
  try {
    raw = JSON.parse(item.json.data);
  } catch (e) {
    return []; // Skip items with unparseable data
  }

  // Ensure the expected structure exists
  if (!Array.isArray(raw) || !raw[0] || !Array.isArray(raw[1])) return [];

  const input_keyword = raw[0].replace(/^=/, '');
  const timestamp = new Date().toISOString();

  return raw[1].map(s => ({
    json: {
      input_keyword,
      suggestion: s,
      timestamp
    }
  }));
});

