return $input.all().flatMap(item => {
  // Skip error items with no data field
  if (!item.json.data) return [];

  let parsed;
  try {
    const json = item.json.data
      .replace(/.*?\.h\(/, '')  // strip the window.google.ac.h( wrapper
      .replace(/\)$/, '');       // strip the trailing )
    parsed = JSON.parse(json);
  } catch (e) {
    return []; // Skip malformed data
  }

  // Validate structure before accessing
  if (!Array.isArray(parsed) || !parsed[0] || !Array.isArray(parsed[1])) return [];

  const input_keyword = parsed[0].replace(/^=/, '');
  const timestamp = new Date().toISOString();

  return parsed[1].map(s => ({
    json: {
      input_keyword,
      suggestion: s[0],
      timestamp
    }
  }));
});

