return $input.all().flatMap(item => {
  if (!item.json.query || !item.json.organic) {
    // Optionally surface the error as a row
    return [{
      json: {
        error: true,
        error_status: item.json.error?.status ?? null,
        error_message: item.json.error?.message ?? 'Unknown error',
        timestamp: new Date().toISOString()
      }
    }];
  }

  const results = item.json.organic;
  const keyword = item.json.query.q.replace(/^=/, '');

  return results.map(r => ({
    json: {
      input_keyword: keyword,
      position: r.position,
      url: r.url,
      title: r.title,
      source: 'zenserp',
      timestamp: new Date().toISOString()
    }
  }));
});

return $input.all().map(item => {
	const html = item.json.data || '';

	const text = html
		.replace(/<script[\s\S]*?<\/script>/gi, '')
		.replace(/<style[\s\S]*?<\/style>/gi, '')
		.replace(/<[^>]+>/g, ' ')
		.replace(/\s+/g, ' ')
		.trim()
		.slice(0, 5000);

	return {
		json: {
			input_keyword: item.json.input_keyword,
			position: item.json.position,
			url: item.json.url,
			title: item.json.title,
			content: text,
			timestamp: item.json.timestamp
		}
	};
});

const items = $input.all();
const seen = new Set();
const result = [];

for (const item of items) {
  const content = item.json.content;
  if (!content) continue;
  const normalized = content.trim().toLowerCase().slice(0, 100); // compare first 100 chars
  if (!seen.has(normalized)) {
    seen.add(normalized);
    result.push(item);
  }
}

return result;

